 return assemble_family(repo,source_ref,'electric-gravity-balance',TASKS,CHOICES,UNITS,'electric-gravity-balance-progressive.svg',FIGURES,19900,unit='u6',course='C4',source_path='packages/engine/lessonos/study/content/physics-semestre-2026-bank/questions/U6-01.json',skill='C4-L02',prerequisites=['C1-L001','C1-L002','C1-L005','C1-L006','C4-L01','C4-L02'],section='Equilibrio elettrico e forza peso',coverage=['Somma delle forze con segno','Conversioni milligrammi e microcoulomb','Inverse, rapporti, medie e tarature','Vincolo e scala continua non identificata'])
